let colors = ["red", "green", "blue"];

colors.forEach(function(color) {
  console.log(color);
});
// Output:
// red
// green
// blue

let fruits = ["apple", "banana", "cherry"];

fruits.forEach(function(fruit, index) {
  console.log(index + ": " + fruit);
});
// Output:
// 0: apple
// 1: banana
// 2: cherry

let numbers = [1, 2, 3, 4];
let doubled = numbers.map(function(num) {
  return num * 2;
});

console.log(doubled);   // [2, 4, 6, 8]
console.log(numbers);   // [1, 2, 3, 4] — unchanged

let names = ["alex", "sam", "jordan"];
let capitalized = names.map(name => name[0].toUpperCase() + name.slice(1));

console.log(capitalized);  // ["Alex", "Sam", "Jordan"]

let numbers = [1, 2, 3, 4, 5, 6];
let evens = numbers.filter(function(num) {
  return num % 2 === 0;
});

console.log(evens);     // [2, 4, 6]
console.log(numbers);   // [1, 2, 3, 4, 5, 6] — unchanged

let users = [
  { name: "Alex", age: 25 },
  { name: "Sam", age: 17 },
  { name: "Jordan", age: 30 }
];

let adults = users.filter(user => user.age >= 18);

console.log(adults);
// [{ name: "Alex", age: 25 }, { name: "Jordan", age: 30 }]

let nums = [1, 2, 3, 4, 5];

let total = nums.reduce(function(acc, num) {
  return acc + num;
}, 0);

console.log(total);  // 15

let fruits = ["apple", "banana", "apple", "orange", "banana", "apple"];

let counts = fruits.reduce(function(acc, fruit) {
  acc[fruit] = (acc[fruit] || 0) + 1;
  return acc;
}, {});

console.log(counts);  // { apple: 3, banana: 2, orange: 1 }

let users = [
  { name: "Alex", age: 25 },
  { name: "Sam", age: 17 },
  { name: "Jordan", age: 30 }
];

let minor = users.find(user => user.age < 18);
console.log(minor);  // { name: "Sam", age: 17 }

let index = users.findIndex(user => user.age < 18);
console.log(index);  // 1

let nums = [1, 2, 3, 4, 5];

// includes — does the array contain this value?
console.log(nums.includes(3));     // true
console.log(nums.includes(99));    // false

// some — does at least one element pass?
console.log(nums.some(n => n > 4));   // true

// every — do all elements pass?
console.log(nums.every(n => n > 0));  // true
console.log(nums.every(n => n > 3));  // false

let nums = [40, 1, 5, 200, 10];

// WRONG: default sort treats numbers as strings
// nums.sort();  // [1, 10, 200, 40, 5]

// RIGHT: use a comparator
nums.sort(function(a, b) {
  return a - b;
});

console.log(nums);  // [1, 5, 10, 40, 200]

let original = [3, 1, 4, 1, 5, 9];
let sorted = original.toSorted((a, b) => a - b);

console.log(sorted);    // [1, 1, 3, 4, 5, 9]
console.log(original);  // [3, 1, 4, 1, 5, 9] — unchanged!
